// Manual constructor - no @Autowired needed
@Service
class OrderService {
    private final OrderRepository orderRepo;
    private final EmailService emailService;

    // Single constructor, Spring auto-wires it
    public OrderService(OrderRepository orderRepo, EmailService emailService) {
        this.orderRepo = orderRepo;
        this.emailService = emailService;
    }

    public void placeOrder(Order order) {
        orderRepo.save(order);
        emailService.sendConfirmation(order);
    }
}

// Lombok version - even cleaner
@Service
@RequiredArgsConstructor  // generates constructor for final fields
class OrderService {
    private final OrderRepository orderRepo;
    private final EmailService emailService;

    public void placeOrder(Order order) {
        orderRepo.save(order);
        emailService.sendConfirmation(order);
    }
}

// Multiple constructors - need @Autowired on one
@Service
class ProductService {
    private final ProductRepository repo;

    @Autowired  // required because there are 2 constructors
    public ProductService(ProductRepository repo) {
        this.repo = repo;
    }

    public ProductService() {
        this.repo = new InMemoryProductRepository();
    }
}
