@Service
public class CustomerService {
    // Required dependencies - constructor injection
    private final CustomerRepository repository;
    private final ValidationService validator;

    // Optional dependencies - setter injection
    private CacheManager cacheManager;
    private NotificationService notificationService;

    // Constructor for required dependencies
    public CustomerService(CustomerRepository repository, 
                          ValidationService validator) {
        this.repository = repository;
        this.validator = validator;
    }

    // Setters for optional dependencies
    @Autowired(required = false)
    public void setCacheManager(CacheManager cacheManager) {
        this.cacheManager = cacheManager;
    }

    @Autowired(required = false)
    public void setNotificationService(NotificationService notificationService) {
        this.notificationService = notificationService;
    }

    public Customer createCustomer(CustomerDto dto) {
        validator.validate(dto); // required, always available
        var customer = repository.save(dto.toEntity());

        if (cacheManager != null) { // optional feature
            cacheManager.put(customer.getId(), customer);
        }
        if (notificationService != null) { // optional feature
            notificationService.sendWelcomeEmail(customer);
        }
        return customer;
    }
}
